@orders_bp.route("/<int:order_id>", methods=["GET"])
@require_auth
def get_order(order_id: int):
    """Fetch a single order by id."""
    session = get_session()
    order = session.get(Order, order_id)
    if order is None:
        return jsonify({"error": "not found"}), 404
    return jsonify(order.to_dict())

def require_auth(fn):
    """Reject the request unless a valid user token is presented."""

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.current_user = user
        return fn(*args, **kwargs)

    return wrapper

def is_owner_or_admin(user: User, owner_id: int) -> bool:
    """Ownership check used for per-object access (orders, profiles)."""
    return user.id == owner_id or user.role == "admin"

@users_bp.route("/<int:user_id>", methods=["GET"])
@require_auth
def get_user(user_id: int):
    """Fetch a user profile. Owner or admin only."""
    if not is_owner_or_admin(g.current_user, user_id):
        return jsonify({"error": "forbidden"}), 403
    session = get_session()
    user = session.get(User, user_id)
    if user is None:
        return jsonify({"error": "not found"}), 404
    return jsonify(user.to_dict(include_email=True))

class Order(Base):
    __tablename__ = "orders"

    id = Column(Integer, primary_key=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=False)
    ...
    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "user_id": self.user_id,
            "status": self.status,
            "total": self.total,
            "shipping_address": self.shipping_address,
        }

